mapper.select:
SELECT training_id as trainingId, model_type as modelType, training_status as trainingStatus, progress, start_time as startTime, end_time as endTime, elapsed_time as elapsedTime, accuracy FROM ml_training_history
AND model_type = #{modelType}
ORDER BY training_id DESC
LIMIT #{limit}

-- 从diet_recommendation表直接统计真实数据（替换假数据） SELECT CAST(COUNT(*) AS SIGNED) as totalRecommendations, CAST(COUNT(CASE WHEN is_accepted = '1' THEN 1 END) AS SIGNED) as acceptedRecommendations, ROUND( COALESCE( COUNT(CASE WHEN is_accepted = '1' THEN 1 END) * 1.0 / NULLIF(COUNT(CASE WHEN is_accepted IS NOT NULL AND is_accepted != '' THEN 1 END), 0), 0 ), 4 ) as acceptanceRate, ROUND(COALESCE(AVG(score), 0), 2) as avgScore, CAST(COUNT(DISTINCT user_id) AS SIGNED) as activeUsers, CAST(ROUND(COALESCE(AVG(response_time), 75), 0) AS SIGNED) as avgResponseTime FROM diet_recommendation
AND recommendation_date >= #{startDate}
AND recommendation_date <= #{endDate}
